fn swap_first_and_last(a: &mut Vec<i32>) {
    // Spec: requires no precondition (any vector is fine)
    // ensures that the resulting vector is a permutation of the original,
    // and that the first and last elements have swapped places if length > 1,
    // otherwise unchanged.
    #[verifier::spec]
    fn permutes_after_swap(orig: &Vec<i32>, res: &Vec<i32>) -> bool {
        // Since only first and last elements swap if length > 1,
        // the multiset (bag) of elements remain identical
        orig.len() == res.len() &&
        orig.iter().collect::<std::collections::HashSet<_>>() ==
        res.iter().collect::<std::collections::HashSet<_>>() &&
        // if length > 1, res[0] == orig[last], res[last] == orig[0]
        // and all intermediate elements unchanged
        if orig.len() > 1 {
            res[0] == orig[orig.len() - 1] &&
            res[orig.len() - 1] == orig[0] &&
            (1..orig.len()-1).all(|i| res[i] == orig[i])
        } else {
            // Otherwise vectors equal
            *res == *orig
        }
    }

    let len = a.len();
    if len > 1 {
        // Capture original vector snapshot
        let orig = a.clone();
        a.swap(0, len - 1);
        // Ensure that the swap results in the expected permutation
        assert(permutates_after_swap(&orig, &*a));
    } else {
        // If length <=1, a remains unchanged
        let orig = a.clone();
        // no-op, so vector unchanged
        assert(*a == orig);
    }
}